/**
 * Fog Post — o pós-processamento comum às cenas de névoa (`fog-tree`,
 * `fog-garden`): render → rastro de longa exposição → duotone com grão.
 *
 * ── Por que duotone e não material colorido ────────────────────────────────
 *
 * A cena inteira é desenhada em CINZA (céu branco, névoa branca, tronco e copa
 * em cinzas numéricos) e só no último passe a luminância vira a mistura de dois
 * tokens: `paper` nas luzes, `ink` nas sombras. Três ganhos de uma vez:
 *
 * 1. **Nenhuma cor mora na cena.** Troca de marca é troca de dois uniforms.
 * 2. **O dark mode sai de graça.** No escuro, `--background` é escuro e
 *    `--foreground` é claro, então o mesmo passe inverte a foto: árvore clara
 *    numa névoa noturna, sem segunda paleta.
 * 3. **A névoa nunca briga com a marca.** FogExp2 tende ao branco da cena, e o
 *    branco da cena É o papel da marca depois do passe.
 *
 * ── As cores entram cruas no shader, de propósito ─────────────────────────
 *
 * `ShaderMaterial` não passa pela conversão de espaço de cor do three: o que o
 * fragment escreve vai direto para o canvas sRGB. O `resolveCssColor` já
 * devolve sRGB 0..1, então o uniform recebe esses números sem conversão
 * (`setRGB` no espaço de trabalho não converte). Passar por `Color.set(css)`
 * linearizaria o papel e ele sairia um tom mais escuro que o fundo da página —
 * a costura entre o canvas e o resto da seção fica visível.
 *
 * ── O rastro ───────────────────────────────────────────────────────────────
 *
 * `AfterimagePass` mistura o quadro novo com o anterior (`damp` 0..1). Com a
 * câmera andando, o vento nas folhas vira longa exposição em vez de tremor.
 * Com movimento reduzido o passe nem entra na cadeia: rastro sem movimento é
 * só um passe de GPU pago à toa.
 */

import * as THREE from "three";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { AfterimagePass } from "three/examples/jsm/postprocessing/AfterimagePass.js";
import { ShaderPass } from "three/examples/jsm/postprocessing/ShaderPass.js";

import type { RGB } from "@/lib/css-color";

/**
 * O passe final. `TAPS` amostras em círculo, com raio que cresce longe do
 * centro: a borda fica mais sonhadora que o miolo, como lente velha. O modo
 * leve corta as amostras pela metade — é o laço mais caro do quadro.
 */
const fragmentShader = /* glsl */ `
  uniform sampler2D tDiffuse;
  uniform vec3 uPaper, uInk;
  uniform float uTime, uGrain, uVignette;
  uniform vec2 uRes;
  varying vec2 vUv;

  float hash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
  }

  void main() {
    vec2 c = vUv - 0.5;
    float r = length(c * vec2(uRes.x / uRes.y, 1.0));
    vec3 acc = texture2D(tDiffuse, vUv).rgb;
    float raio = 1.6 * (1.0 + 3.0 * smoothstep(0.2, 0.9, r));
    for (int i = 0; i < TAPS; i++) {
      float a = float(i) * (6.2831853 / float(TAPS));
      acc += texture2D(tDiffuse, vUv + vec2(cos(a), sin(a)) * raio / uRes).rgb;
    }
    float L = dot(acc / float(TAPS + 1), vec3(0.299, 0.587, 0.114));
    L = smoothstep(0.02, 0.98, L);
    vec3 col = mix(uInk, uPaper, L);
    // a borda volta ao papel: a cena termina dentro da seção, sem moldura
    col = mix(col, uPaper, smoothstep(0.55, 1.1, r) * uVignette);
    // grão em células de 1.5px, sorteado a 24 quadros por segundo (cadência de
    // película); por pixel e por quadro ele vira chiado de TV
    float g = hash(floor(gl_FragCoord.xy / 1.5) + mod(floor(uTime * 24.0), 64.0) * 37.0) - 0.5;
    gl_FragColor = vec4(col + g * uGrain, 1.0);
  }
`;

const vertexShader = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const BRANCO = new THREE.Color(1, 1, 1);

export interface FogPostOptions {
  /** Rastro (damp do AfterimagePass), 0..0.98. 0 tira o passe da cadeia. */
  trail?: number;
  /** Intensidade do grão, 0..0.2. */
  grain?: number;
  /** Quanto a borda volta ao papel, 0..1. */
  vignette?: number;
  /** Modo leve: metade das amostras de desfoque. */
  light?: boolean;
}

export interface FogPost {
  setSize(w: number, h: number): void;
  setColors(paper: RGB, ink: RGB): void;
  /** Tempo em segundos — só o grão lê. Congelado, o grão fica parado. */
  setTime(t: number): void;
  render(): void;
  /**
   * Zera o rastro. Sem isto, voltar de uma aba escondida mostra por alguns
   * quadros o fantasma do último quadro de minutos atrás.
   */
  resetTrail(): void;
  dispose(): void;
}

export function createFogPost(
  renderer: THREE.WebGLRenderer,
  scene: THREE.Scene,
  camera: THREE.Camera,
  { trail = 0.86, grain = 0.05, vignette = 0.55, light = false }: FogPostOptions = {},
): FogPost {
  const composer = new EffectComposer(renderer);
  composer.addPass(new RenderPass(scene, camera));

  const damp = THREE.MathUtils.clamp(trail, 0, 0.98);
  const rastro = damp > 0 ? new AfterimagePass(damp) : null;
  if (rastro) composer.addPass(rastro);

  const final = new ShaderPass({
    uniforms: {
      tDiffuse: { value: null },
      // pretos até o primeiro setColors; a cena chama logo depois de nascer
      uPaper: { value: new THREE.Color(1, 1, 1) },
      uInk: { value: new THREE.Color(0, 0, 0) },
      uTime: { value: 0 },
      uGrain: { value: grain },
      uVignette: { value: vignette },
      uRes: { value: new THREE.Vector2(1, 1) },
    },
    defines: { TAPS: light ? 4 : 8 },
    vertexShader,
    fragmentShader,
  });
  composer.addPass(final);

  return {
    setSize(w, h) {
      composer.setSize(w, h);
      final.uniforms.uRes.value.set(w, h);
    },
    setColors(paper, ink) {
      (final.uniforms.uPaper.value as THREE.Color).setRGB(...paper);
      (final.uniforms.uInk.value as THREE.Color).setRGB(...ink);
    },
    setTime(t) {
      final.uniforms.uTime.value = t;
    },
    render() {
      composer.render();
    },
    resetTrail() {
      if (!rastro) return;
      // os dois alvos do afterimage guardam a memória; limpar ambos
      const prev = renderer.getRenderTarget();
      const cor = renderer.getClearColor(new THREE.Color());
      const alfa = renderer.getClearAlpha();
      // branco = papel depois do duotone: o rastro recomeça da névoa, não do preto
      renderer.setClearColor(BRANCO, 1);
      for (const rt of [rastro.textureComp, rastro.textureOld]) {
        renderer.setRenderTarget(rt);
        renderer.clear();
      }
      renderer.setRenderTarget(prev);
      renderer.setClearColor(cor, alfa);
    },
    dispose() {
      rastro?.dispose();
      final.dispose();
      composer.dispose();
    },
  };
}

/**
 * Cinza sRGB 0..1 como o número que `ez-tree` espera em `tint`.
 *
 * O ez-tree lê `tint` como inteiro de cor. Escrever o literal no código seria
 * hex numa pasta que proíbe hex — e, pior, esconderia que o valor é uma
 * LUMINÂNCIA para o duotone, não uma cor. `SRGBColorSpace` explícito para o
 * número sair igual ao que a mão escreveria; sem ele o `Color` lê os floats
 * como lineares e devolve um cinza mais claro.
 */
export function grayTint(v: number): number {
  return gray(v).getHex();
}

/** Cinza sRGB 0..1 como `THREE.Color` — para chão, luz e materiais da cena. */
export function gray(v: number): THREE.Color {
  return new THREE.Color().setRGB(v, v, v, THREE.SRGBColorSpace);
}

/**
 * Sombra de contato: gradiente radial num canvas, sem textura baixada.
 *
 * Na névoa não há sombra projetada que se leia — a luz é difusa. O que ancora
 * a árvore no chão é a mancha escura logo abaixo da copa, e um shadow map de
 * verdade custaria um passe de profundidade inteiro por esse efeito.
 */
export function contactShadowTexture(size = 256, strength = 0.38): THREE.CanvasTexture {
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const g = c.getContext("2d");
  if (g) {
    const h = size / 2;
    const grd = g.createRadialGradient(h, h, 0, h, h, h);
    grd.addColorStop(0, `rgba(0,0,0,${strength})`);
    grd.addColorStop(0.58, `rgba(0,0,0,${strength * 0.4})`);
    grd.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = grd;
    g.fillRect(0, 0, size, size);
  }
  return new THREE.CanvasTexture(c);
}

/** Descarta geometria e material de tudo abaixo de `root`. Textura fica: quem
 *  a criou é quem a guarda (as do ez-tree são cache de módulo, compartilhadas
 *  entre montagens — descartá-las quebraria a próxima árvore). */
export function disposeTree(root: THREE.Object3D) {
  root.traverse((o) => {
    const m = o as THREE.Mesh;
    m.geometry?.dispose();
    const mats = Array.isArray(m.material) ? m.material : m.material ? [m.material] : [];
    mats.forEach((mat) => mat.dispose());
  });
}

/**
 * Cria o renderer das cenas de névoa, ou devolve `null` se o WebGL não existir.
 *
 * `null` e não exceção: máquina sem WebGL (driver na lista negra, VM, modo de
 * economia) tem de ver a seção com o papel liso e o texto por cima, não uma
 * tela de erro. O componente já pinta o papel por baixo do canvas.
 */
export function createFogRenderer(canvas: HTMLCanvasElement, light: boolean) {
  try {
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: !light,
      powerPreference: "high-performance",
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, light ? 1 : 1.5));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    return renderer;
  } catch {
    return null;
  }
}

/**
 * Devolve o contexto ao navegador já, em vez de esperar o GC.
 *
 * O teto é ≈16 contextos vivos no Chrome. Uma SPA que entra e sai de rota com
 * cena 3D estoura esse teto sem nunca ter duas cenas na tela — e o sintoma é a
 * cena MAIS ANTIGA perdendo o contexto, sem erro que aponte para cá.
 */
export function releaseRenderer(renderer: THREE.WebGLRenderer) {
  renderer.dispose();
  try {
    renderer.forceContextLoss();
  } catch {
    /* contexto já perdido */
  }
}

/**
 * Fog Tree Scene — a cena do `fog-tree`, em three puro (sem react-three-fiber).
 *
 * Árvore procedural do `@dgreenheck/ez-tree` (MIT), FogExp2, rastro de longa
 * exposição e o duotone do `fog-post`. Vive num arquivo próprio para ser
 * carregada por `import()` só quando a seção chega perto da tela: o ez-tree
 * embute as texturas de casca e folha no bundle, e isso não pode entrar no
 * chunk de quem só renderiza o texto da seção.
 *
 * ── Por que three puro e não fiber ─────────────────────────────────────────
 *
 * A cena é UM objeto, sem estado React dentro: progresso, cor e arrasto chegam
 * por método, 60× por segundo, sem re-render. O fiber cobraria a reconciliação
 * e a linha de versão travada (fiber 8 × React 18, ver `book-3d`) para ganhar
 * nada aqui.
 *
 * Também exporta `growTree`, que o `fog-garden` usa para gerar as variantes do
 * jardim com os mesmos cinzas — as duas cenas têm de ser da mesma floresta.
 */

import * as THREE from "three";
import { Tree, TreePreset } from "@dgreenheck/ez-tree";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";

import type { RGB } from "@/lib/css-color";
import {
  contactShadowTexture,
  createFogPost,
  createFogRenderer,
  disposeTree,
  gray,
  grayTint,
  releaseRenderer,
} from "@/lib/fog-post";

/** Os presets do ez-tree, menos a treliça (que não é árvore). */
export type FogTreePreset = Exclude<keyof typeof TreePreset, "Trellis">;

type TreeOptions = Tree["options"];

/**
 * Cinzas do tronco e da copa, em luminância sRGB.
 *
 * Tronco bem escuro e copa no meio da escala: depois do duotone o tronco lê
 * como tinta e a copa como tinta diluída, que é como a névoa come a folhagem
 * antes do tronco numa foto de verdade. Copa escura demais vira um borrão
 * chapado; clara demais some na névoa antes do tronco aparecer.
 */
export const TREE_GRAYS = { bark: 0.165, leaves: 0.435 };

/**
 * A copa redonda da referência (a árvore solitária na neblina).
 *
 * O `Oak Medium` cru sai alto e ralo; estes ajustes o deixam com a copa cheia e
 * baixa e o tronco aparente, que é o que faz a silhueta ler de longe, no meio
 * da névoa. Só se aplica ao preset padrão: nos outros, mexer em ângulo e
 * contagem de galho deforma o que o preset tem de característico.
 */
export function roundCrown(t: Tree) {
  Object.assign(t.options.leaves, { count: 30, size: 3.6, angle: 50 });
  Object.assign(t.options.branch.children, { 0: 8, 1: 5, 2: 3 });
  Object.assign(t.options.branch.angle, { 1: 62, 2: 58, 3: 40 });
}

/**
 * Gera uma árvore em cinza, pronta para o duotone.
 *
 * `options.copy` em vez de `loadPreset`: o `loadPreset` do ez-tree já chama
 * `generate()` por dentro, e gerar de novo depois do ajuste dobrava o custo —
 * no jardim são sete variantes, e cada geração bloqueia a thread principal.
 */
export function growTree(
  preset: FogTreePreset,
  seed: number,
  tweak?: (t: Tree) => void,
): Tree {
  const t = new Tree();
  t.options.copy(TreePreset[preset] as unknown as TreeOptions);
  t.options.seed = seed;
  t.options.bark.tint = grayTint(TREE_GRAYS.bark);
  t.options.leaves.tint = grayTint(TREE_GRAYS.leaves);
  tweak?.(t);
  t.generate();
  return t;
}

export interface FogTreeSceneOptions {
  preset: FogTreePreset;
  seed: number;
  /** Densidade da névoa no começo e no fim do progresso (unidades relativas à
   *  altura da árvore: 1 ≈ a árvore some na distância inicial da câmera). */
  fog: { start: number; end: number };
  trail: number;
  grain: number;
  draggable: boolean;
  reduce: boolean;
  /** Toque ou tela pequena: menos folhas, pixel ratio 1, desfoque mais barato. */
  light: boolean;
}

export interface FogTreeScene {
  setProgress(p: number): void;
  setColors(paper: RGB, ink: RGB): void;
  setRunning(on: boolean): void;
  setDraggable(on: boolean): void;
  dispose(): void;
}

/** `null` quando não há WebGL — o componente fica com o papel liso. */
export function createFogTreeScene(
  canvas: HTMLCanvasElement,
  opts: FogTreeSceneOptions,
): FogTreeScene | null {
  const renderer = createFogRenderer(canvas, opts.light);
  if (!renderer) return null;

  const scene = new THREE.Scene();
  const branco = gray(1);
  scene.background = branco;
  const fog = new THREE.FogExp2(branco, 0.02);
  scene.fog = fog;

  const camera = new THREE.PerspectiveCamera(32, 1, 0.1, 2000);
  scene.add(new THREE.HemisphereLight(branco, gray(0.604), 2.2));
  const sol = new THREE.DirectionalLight(branco, 1.2);
  sol.position.set(20, 60, 30);
  scene.add(sol);

  const tree = growTree(opts.preset, opts.seed, (t) => {
    if (opts.preset === "Oak Medium") roundCrown(t);
    // menos folha no modo leve: é a maior contagem de vértice da cena
    if (opts.light) t.options.leaves.count = Math.round(t.options.leaves.count * 0.6);
  });
  scene.add(tree);

  const box = new THREE.Box3().setFromObject(tree);
  const size = box.getSize(new THREE.Vector3());
  const altura = size.y;
  const copaY = box.min.y + altura * 0.62;

  // Chão quase branco: depois do duotone vira papel, e a linha do horizonte
  // dissolve na névoa em vez de cortar a cena.
  const chaoGeo = new THREE.PlaneGeometry(altura * 40, altura * 40);
  const chaoMat = new THREE.MeshBasicMaterial({ color: gray(0.957) });
  const chao = new THREE.Mesh(chaoGeo, chaoMat);
  chao.rotation.x = -Math.PI / 2;
  chao.position.y = box.min.y;
  scene.add(chao);

  const sombraTex = contactShadowTexture(256, 0.38);
  const sombraGeo = new THREE.PlaneGeometry(size.x * 1.5, size.x * 1.1);
  const sombraMat = new THREE.MeshBasicMaterial({
    map: sombraTex,
    transparent: true,
    depthWrite: false,
  });
  const sombra = new THREE.Mesh(sombraGeo, sombraMat);
  sombra.rotation.x = -Math.PI / 2;
  sombra.position.y = box.min.y + 0.05;
  scene.add(sombra);

  const post = createFogPost(renderer, scene, camera, {
    trail: opts.reduce ? 0 : opts.trail,
    grain: opts.grain,
    light: opts.light,
  });

  /*
   * Órbita: o controle decide só o ÂNGULO. A distância é do progresso (abaixo),
   * reescrita a cada quadro — por isso zoom e pan desligados, e o polar preso
   * numa faixa estreita: abaixo dela a câmera entra no chão, acima ela vira
   * planta baixa e a árvore perde a silhueta.
   *
   * Sem `domElement` quando não é arrastável. O OrbitControls põe
   * `touch-action: none` no elemento ao conectar, e isso mata o scroll vertical
   * de quem encosta o dedo na árvore — no celular, a seção vira uma armadilha.
   * O giro ocioso continua: ele roda no `update()`, não depende de evento.
   */
  const foco = new THREE.Vector3(0, copaY * 0.82, 0);
  camera.position.set(0, copaY * 0.55, altura * 3.6);
  const controls = new OrbitControls(camera, null);
  controls.target.copy(foco);
  controls.enableZoom = false;
  controls.enablePan = false;
  controls.enableDamping = !opts.reduce;
  controls.dampingFactor = 0.05;
  controls.rotateSpeed = 0.45;
  controls.minPolarAngle = Math.PI * 0.36;
  controls.maxPolarAngle = Math.PI * 0.53;
  controls.autoRotate = !opts.reduce;
  controls.autoRotateSpeed = 0.25;
  let arrastando = false;
  const pegar = () => {
    arrastando = true;
    controls.autoRotate = false;
  };
  const soltar = () => {
    arrastando = false;
    controls.autoRotate = !opts.reduce;
  };
  controls.addEventListener("start", pegar);
  controls.addEventListener("end", soltar);
  // com movimento reduzido não há laço: cada arrasto pede o seu quadro
  controls.addEventListener("change", () => pedir());

  let conectado = false;
  const setDraggable = (on: boolean) => {
    if (on === conectado) return;
    conectado = on;
    if (on) {
      controls.domElement = canvas;
      controls.connect();
    } else {
      controls.disconnect();
      soltar();
    }
  };
  setDraggable(opts.draggable);

  const resize = () => {
    const w = Math.max(1, canvas.clientWidth);
    const h = Math.max(1, canvas.clientHeight);
    renderer.setSize(w, h, false);
    post.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    pedir();
  };
  const ro = new ResizeObserver(resize);
  ro.observe(canvas);

  const alvo = { p: 0 };
  const atual = { p: 0 };
  const dir = new THREE.Vector3();
  const relogio = new THREE.Clock();
  let visivel = false;
  let raf = 0;

  const quadro = () => {
    const t = relogio.getElapsedTime();
    // O progresso chega com inércia própria além da mola do componente: a mola
    // suaviza o scroll, esta suaviza o progresso passado à mão (número cru).
    atual.p += (alvo.p - atual.p) * (opts.reduce ? 1 : 0.06);

    controls.update();
    // Retrato: a copa é mais larga que a tela estreita e sairia cortada nos
    // lados. Recuar pela raiz da proporção devolve a silhueta sem afastar a
    // árvore tanto que ela vire um ponto.
    const retrato = camera.aspect < 0.8 ? Math.sqrt(0.8 / camera.aspect) : 1;
    const dist = THREE.MathUtils.lerp(altura * 3.1, altura * 2.2, atual.p) * retrato;
    dir.subVectors(camera.position, foco).normalize();
    camera.position.copy(foco).addScaledVector(dir, dist);
    camera.lookAt(foco);
    fog.density = THREE.MathUtils.lerp(opts.fog.start, opts.fog.end, atual.p) / (altura * 3);

    if (!opts.reduce) {
      // a árvore inteira balança quase nada, além do vento do shader nas folhas
      tree.rotation.z = Math.sin(t * 0.6) * 0.012;
      tree.update(t);
      post.setTime(t);
    }
    post.render();
  };

  const animando = () =>
    visivel && (!opts.reduce || arrastando || Math.abs(alvo.p - atual.p) > 1e-4);

  // `raf` só zera DEPOIS do quadro: o `controls.update()` lá dentro dispara
  // "change", que chama `pedir()` — com `raf` já zerado, cada quadro agendaria
  // dois, e o laço dobraria a cada volta.
  const tick = () => {
    quadro();
    raf = animando() ? requestAnimationFrame(tick) : 0;
  };
  function pedir() {
    if (visivel && !raf) raf = requestAnimationFrame(tick);
  }

  resize();

  return {
    setProgress(p) {
      alvo.p = THREE.MathUtils.clamp(p, 0, 1);
      pedir();
    },
    setColors(paper, ink) {
      post.setColors(paper, ink);
      pedir();
    },
    setRunning(on) {
      if (on === visivel) return;
      visivel = on;
      if (on) {
        post.resetTrail();
        pedir();
      } else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    },
    setDraggable,
    dispose() {
      visivel = false;
      if (raf) cancelAnimationFrame(raf);
      ro.disconnect();
      controls.removeEventListener("start", pegar);
      controls.removeEventListener("end", soltar);
      controls.dispose();
      disposeTree(tree);
      chaoGeo.dispose();
      chaoMat.dispose();
      sombraGeo.dispose();
      sombraMat.dispose();
      sombraTex.dispose();
      post.dispose();
      releaseRenderer(renderer);
    },
  };
}

"use client";

/**
 * Fog Tree — uma árvore procedural sozinha na névoa, em duotone da marca.
 *
 * Colhido de um site de cliente (2026-10), onde a seção do tema central leva a câmera
 * para dentro do jardim com o scroll enquanto a névoa abre. A peça vale fora
 * dali porque o efeito é de marca nenhuma: a cena é desenhada em cinza e só o
 * último passe pinta com `--background` (papel) e `--foreground` (tinta). Troca
 * de tema inverte a foto inteira; troca de marca troca dois tokens.
 *
 * Decisões que sobrevivem à colheita:
 *
 * 1. **O WebGL só desce perto da tela.** A cena mora em `@/lib/fog-tree-scene`
 *    e entra por `import()` quando a peça passa a 400px da viewport. O ez-tree
 *    embute as texturas no bundle; quem nunca rola até a seção não paga.
 * 2. **Fora da tela e com a aba escondida, zero quadro.** O laço para (não
 *    "renderiza menos"): GPU de notebook esquenta com cena parada rodando atrás
 *    do texto que a pessoa está lendo.
 * 3. **Arrastar só com ponteiro fino, por padrão.** O OrbitControls trava o
 *    `touch-action` do canvas, e no celular encostar na árvore deixaria de
 *    rolar a página. `draggable` força qualquer um dos lados.
 * 4. **Mola ANTES de qualquer transform, no modo `scroll`.** `useScroll` +
 *    `useTransform` direto é acelerado pelo ScrollTimeline nativo e erra a
 *    faixa dentro de `position: sticky` — medido no site de origem. A mola tira
 *    a cadeia do caminho nativo e ainda dá peso à câmera.
 * 5. **Movimento reduzido não é cena congelada às cegas.** Sem giro ocioso, sem
 *    vento, sem rastro e sem grão animado — mas o scroll ainda aproxima a câmera
 *    (é posição, não animação) e o arrasto ainda gira, quadro a quadro, sem
 *    laço contínuo.
 * 6. **Sem WebGL, o papel.** Se o contexto não nasce, a seção fica com o fundo
 *    do token e o texto por cima — nunca uma caixa de erro.
 *
 * Requer `three`, `@dgreenheck/ez-tree` e `framer-motion`.
 */

import * as React from "react";
import {
  isMotionValue,
  useMotionValue,
  useReducedMotion,
  useScroll,
  useSpring,
  type MotionValue,
} from "framer-motion";

import { cn } from "@/lib/utils";
import { onThemeChange, resolveCssColor } from "@/lib/css-color";
import type { FogTreePreset, FogTreeScene } from "@/lib/fog-tree-scene";

export type { FogTreePreset };

export interface FogTreeProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "children"> {
  /**
   * Progresso 0..1 da caminhada: 0 é a árvore inteira ao longe, 1 é a câmera
   * debaixo da copa com a névoa aberta. Número ou `MotionValue` (o de um
   * `useScroll` seu, por exemplo). Ignorado com `scroll`.
   */
  progress?: number | MotionValue<number>;
  /**
   * Prende o progresso ao scroll da própria seção: a peça vira uma `<section>`
   * com `scrollLength` de altura e o palco fica preso (sticky) na tela.
   */
  scroll?: boolean;
  /** Altura da seção no modo `scroll`. Quanto maior, mais lenta a caminhada. */
  scrollLength?: string;
  /** Cor das luzes. Qualquer cor CSS; o padrão é o token de fundo. */
  paper?: string;
  /** Cor das sombras. O padrão é o token de texto. */
  ink?: string;
  /**
   * Semente do ez-tree. Mesma semente, mesma árvore — em toda visita.
   * @min 1
   * @max 9999
   * @step 1
   */
  seed?: number;
  /** Espécie (preset do ez-tree). O `Oak Medium` ganha a copa redonda. */
  preset?: FogTreePreset;
  /** Densidade da névoa no começo e no fim do progresso. ~0.5 a 1.5. */
  fog?: { start?: number; end?: number };
  /** Girar arrastando. Padrão: só com ponteiro fino (mouse, caneta). */
  draggable?: boolean;
  /**
   * Rastro de longa exposição. 0 desliga.
   * @min 0
   * @max 0.98
   * @step 0.01
   */
  trail?: number;
  /**
   * Grão de película.
   * @min 0
   * @max 0.2
   * @step 0.01
   */
  grain?: number;
  /**
   * Camada por cima da cena, para o texto da seção. Função recebe o progresso
   * efetivo (já com mola no modo `scroll`), para o texto chegar junto da câmera.
   * A camada é `pointer-events: none` — dê `pointer-events-auto` ao que clica.
   */
  children?: React.ReactNode | ((progress: MotionValue<number>) => React.ReactNode);
}

const prefersLight = () =>
  window.matchMedia("(pointer: coarse)").matches || window.innerWidth < 768;

export function FogTree({
  progress,
  scroll = false,
  scrollLength = "220vh",
  paper = "var(--background)",
  ink = "var(--foreground)",
  seed = 4242,
  preset = "Oak Medium",
  fog,
  draggable,
  trail = 0.86,
  grain = 0.05,
  className,
  style,
  children,
  ...props
}: FogTreeProps) {
  const rootRef = React.useRef<HTMLElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const sceneRef = React.useRef<FogTreeScene | null>(null);
  const reduce = useReducedMotion() ?? false;

  // ── Progresso efetivo ────────────────────────────────────────────────────
  // Os três ganchos rodam sempre (regra dos hooks); o modo só escolhe a fonte.
  const { scrollYProgress } = useScroll({
    target: rootRef,
    offset: ["start start", "end end"],
  });
  const sprung = useSpring(scrollYProgress, { stiffness: 120, damping: 30, restDelta: 0.0005 });
  const own = useMotionValue(typeof progress === "number" ? progress : 0);
  const effective = scroll ? sprung : isMotionValue(progress) ? progress : own;

  React.useEffect(() => {
    if (typeof progress === "number") own.set(progress);
  }, [progress, own]);

  React.useEffect(() => {
    sceneRef.current?.setProgress(effective.get());
    return effective.on("change", (v) => sceneRef.current?.setProgress(v));
  }, [effective]);

  // ── Ponteiro fino (SSR devolve falso; o efeito corrige no cliente) ───────
  const [fine, setFine] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(pointer: fine)");
    const read = () => setFine(mq.matches);
    read();
    mq.addEventListener("change", read);
    return () => mq.removeEventListener("change", read);
  }, []);
  const canDrag = draggable ?? fine;

  // ── Cores: token → sRGB, relido quando o tema muda ───────────────────────
  const applyColors = React.useCallback(() => {
    const el = rootRef.current;
    if (!el || !sceneRef.current) return;
    sceneRef.current.setColors(resolveCssColor(paper, el), resolveCssColor(ink, el));
  }, [paper, ink]);
  const applyRef = React.useRef(applyColors);
  applyRef.current = applyColors;

  React.useEffect(() => {
    applyColors();
    // Tema por classe/atributo no <html> E tema por media query: os dois
    // existem por aí, e só um deles dispara o MutationObserver.
    const off = onThemeChange(applyColors);
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    mq.addEventListener("change", applyColors);
    return () => {
      off();
      mq.removeEventListener("change", applyColors);
    };
  }, [applyColors]);

  // ── Ciclo de vida da cena ────────────────────────────────────────────────
  const fogStart = fog?.start ?? 0.85;
  const fogEnd = fog?.end ?? 0.6;
  const dragRef = React.useRef(canDrag);
  dragRef.current = canDrag;

  React.useEffect(() => {
    const canvas = canvasRef.current;
    const root = rootRef.current;
    if (!canvas || !root) return;
    let alive = true;
    let loading = false;
    let near = false;

    const running = () => near && document.visibilityState === "visible";
    const sync = () => sceneRef.current?.setRunning(running());

    const io = new IntersectionObserver(
      ([e]) => {
        near = !!e?.isIntersecting;
        if (near && !sceneRef.current && !loading) {
          loading = true;
          import("@/lib/fog-tree-scene")
            .then(({ createFogTreeScene }) => {
              if (!alive) return;
              const scene = createFogTreeScene(canvas, {
                preset,
                seed,
                fog: { start: fogStart, end: fogEnd },
                trail,
                grain,
                draggable: dragRef.current,
                reduce,
                light: prefersLight(),
              });
              sceneRef.current = scene;
              if (!scene) return;
              applyRef.current();
              scene.setProgress(effective.get());
              sync();
            })
            // chunk que não desce (rede caiu, deploy novo) deixa o papel liso
            .catch(() => {});
        }
        sync();
      },
      { rootMargin: "400px 0px" },
    );
    io.observe(root);
    document.addEventListener("visibilitychange", sync);

    return () => {
      alive = false;
      io.disconnect();
      document.removeEventListener("visibilitychange", sync);
      sceneRef.current?.dispose();
      sceneRef.current = null;
    };
    // `effective` fica de fora: trocar a fonte do progresso não regera a árvore,
    // o efeito acima já reassina. O resto muda a geometria ou o pós — regera.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [preset, seed, fogStart, fogEnd, trail, grain, reduce]);

  React.useEffect(() => {
    sceneRef.current?.setDraggable(canDrag);
  }, [canDrag]);

  const content = typeof children === "function" ? children(effective) : children;

  const stage = (
    <>
      <canvas
        ref={canvasRef}
        aria-hidden
        className={cn(
          "absolute inset-0 block h-full w-full",
          canDrag ? "cursor-grab active:cursor-grabbing" : "pointer-events-none",
        )}
      />
      {content != null && (
        <div className="pointer-events-none relative h-full w-full">{content}</div>
      )}
    </>
  );

  if (scroll) {
    return (
      <section
        ref={rootRef}
        className={cn("relative", className)}
        style={{ height: scrollLength, background: paper, ...style }}
        {...props}
      >
        <div className="sticky top-0 h-svh overflow-hidden">{stage}</div>
      </section>
    );
  }

  return (
    <div
      ref={rootRef as React.RefObject<HTMLDivElement>}
      className={cn("relative isolate h-[70svh] min-h-[420px] w-full overflow-hidden", className)}
      style={{ background: paper, ...style }}
      {...props}
    >
      {stage}
    </div>
  );
}

export default FogTree;
